// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t, address actor) public {
        // Admissible domain: any strictly positive, warp-safe timestamp and any actor.
        t = bound(t, 1, type(uint48).max);
        vm.assume(actor != address(0));

        // Warp to a fresh timestamp strictly greater than pastBlockTime (initially 0).
        vm.warp(t);

        // Fund the actor and drive c through its payable fallback entry.
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");

        // General rule: any call sending exactly 10 ether at a timestamp strictly
        // greater than pastBlockTime succeeds and records that timestamp.
        // The mutant sets pastBlockTime before its checks, so its own
        // require(block.timestamp > pastBlockTime) can never pass: ok is always false.
        assertTrue(ok && c.pastBlockTime() == t);
    }
}
